<?php
require_once __DIR__.'/../includes/db_connect.php';require_once __DIR__.'/../includes/auth.php';requireRole('learner');
$st=$pdo->prepare("SELECT a.*,q.title,c.course_name FROM quiz_attempts a JOIN quizzes q ON q.quiz_id=a.quiz_id JOIN courses c ON c.course_id=q.course_id WHERE a.user_id=? ORDER BY a.submitted_at DESC");$st->execute([$_SESSION['user_id']]);$results=$st->fetchAll();$pageTitle='Quiz Results';require __DIR__.'/../includes/header.php';
?><div class="page-heading"><div><div class="eyebrow">LEARNER PORTAL</div><h1>Quiz Results</h1><p>Review your submitted quiz attempts.</p></div></div><section class="dashboard-card"><div class="table-container"><table><thead><tr><th>Quiz</th><th>Course</th><th>Attempt</th><th>Score</th><th>Date</th></tr></thead><tbody><?php if(!$results):?><tr><td colspan="5">No quiz results yet.</td></tr><?php else:foreach($results as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['course_name'])?></td><td><?=e($r['attempt_number'])?></td><td><strong><?=e($r['score'])?>%</strong></td><td><?=e($r['submitted_at'])?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
